def zero_pole(builder, marker):
    """Return zero(marker) (24-input AND of the complemented marker), restoring the marker."""
    assert len(marker) == 24
    builder.x(marker)
    ladder = builder.alloc_qubits(23)
    builder.init_and(marker[0], marker[1], ladder[0])
    for i in range(1, 23):
        builder.init_and(ladder[i-1], marker[i+1], ladder[i])
    for i in reversed(range(22)):
        if i:
            builder.del_and(ladder[i-1], marker[i+1], ladder[i])
        else:
            builder.del_and(marker[0], marker[1], ladder[0])
    builder.free(ladder[:-1])
    builder.x(marker)
    return ladder[-1]


def previous_pole_bits(builder, current, bits):
    """Return current AND zero(bits) for any bit list, restoring the bits."""
    bits = list(bits)
    builder.x(bits)
    controls = [current] + bits
    n = len(controls)
    ladder = builder.alloc_qubits(n - 1)
    builder.init_and(controls[0], controls[1], ladder[0])
    for i in range(1, n - 1):
        builder.init_and(ladder[i-1], controls[i+1], ladder[i])
    for i in reversed(range(n - 2)):
        if i:
            builder.del_and(ladder[i-1], controls[i+1], ladder[i])
        else:
            builder.del_and(controls[0], controls[1], ladder[0])
    builder.free(ladder[:-1])
    builder.x(bits)
    return ladder[-1]


POLE_BITS = {10: 12, 11: 12, 12: 16, 13: 20, 14: 22}


def pole_bits(gi, marker):
    """Structural carry test: P(gi-1) = P(gi) and zero(marker); a partial test is exact up to 2^-k at the edge weight 2gi-1."""
    k = POLE_BITS.get(gi, 24)
    marker = list(marker)
    return marker[12:24] + marker[:k - 12]


